-- ISSUE-AGE-HEAVY-TICK-DETACH-1 (charter pillar autonomy; issue #1503 / agent_issues 2192).
-- The new issue_age_live_doers_tick trigger ran issue planning, agent_issues writes, and remediation updates inside
-- fleet_tick_heavy's trigger graph. D1 began refusing the heavy heartbeat with "triggers nested too deep", freezing
-- the heavy-tick metric producers and reopening the metric freshness issue. Move the same ordered SQL statements
-- to a bounded 10-minute fleet task so each statement runs outside the heartbeat trigger chain.
-- Prediction: heavy ticks commit again; issue-age replanning/escalation still runs every 10 minutes; the stale-metric
-- count falls to zero after the existing writers resume. Revert by restoring the original trigger and removing the task.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM fleet_crons WHERE name='issue-age-live-doers'; DELETE FROM fleet_tasks WHERE id='issue-age-live-doers'; DELETE FROM fleet_tasks_canonical WHERE id='issue-age-live-doers'; CREATE TRIGGER IF NOT EXISTS issue_age_live_doers_tick AFTER INSERT ON fleet_tick_heavy BEGIN DELETE FROM issue_age_tick_state; INSERT INTO issue_age_tick_state SELECT l.*,COALESCE(NULLIF(k.merge_note,''),NULLIF(k.last_error,''),NULLIF(l.plan_reason,''),'no live task, claim or progressing diagnosis') FROM v_issue_age_ladder l LEFT JOIN issue_plans p ON p.issue_id=l.id LEFT JOIN code_tasks k ON k.id=p.task_id; INSERT INTO issue_age_replans(issue_id,outcome_was,planned_at_was,age_h) SELECT id,plan_outcome,planned_at,age_h FROM issue_age_tick_state s WHERE s.rung<>'new' AND s.doer IS NULL AND s.plan_outcome IN ('not-code','invalid','error','queued') AND COALESCE((SELECT value FROM ops_config WHERE key='issue_age_replan'),'on')<>'off' AND s.planned_at<strftime('%Y-%m-%dT%H:%M:%SZ','now','-120 minutes') AND NOT EXISTS(SELECT 1 FROM issue_age_replans r WHERE r.issue_id=s.id AND r.ts>strftime('%Y-%m-%dT%H:%M:%SZ','now','-120 minutes')) ORDER BY CASE s.priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,s.age_h DESC LIMIT 12; UPDATE issue_plans SET outcome='retry',planned_at='2000-01-01T00:00:00Z',detail=substr('ISSUE-AGE-24H-1 re-plan: '||COALESCE(detail,''),1,600) WHERE issue_id IN(SELECT issue_id FROM issue_age_replans WHERE ts>=strftime('%Y-%m-%dT%H:%M:%SZ','now','-1 minutes')) AND outcome IN('not-code','invalid','error','queued'); INSERT OR IGNORE INTO issue_age_actions(issue_id,rung,priority_was,priority_to,blocker) SELECT id,'8h',priority,CASE priority WHEN 'low' THEN 'medium' WHEN 'medium' THEN 'high' WHEN 'high' THEN 'critical' ELSE priority END,blocker FROM issue_age_tick_state WHERE rung IN('8h','16h','24h') AND doer IS NULL; UPDATE agent_issues SET priority=(SELECT priority_to FROM issue_age_actions WHERE issue_id=agent_issues.id AND rung='8h'),updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE status='open' AND id IN(SELECT issue_id FROM issue_age_actions WHERE rung='8h' AND ts=strftime('%Y-%m-%dT%H:%M:%SZ','now')) AND priority IN('low','medium','high'); INSERT OR IGNORE INTO issue_age_actions(issue_id,rung,priority_was,priority_to,blocker) SELECT id,'16h',priority,'critical',blocker FROM issue_age_tick_state WHERE rung IN('16h','24h') AND doer IS NULL; UPDATE agent_issues SET priority='critical',updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE status='open' AND priority<>'critical' AND id IN(SELECT issue_id FROM issue_age_actions WHERE rung='16h' AND ts=strftime('%Y-%m-%dT%H:%M:%SZ','now')); INSERT OR IGNORE INTO issue_age_actions(issue_id,rung,blocker) SELECT id,'24h',blocker FROM issue_age_tick_state WHERE breach=1; INSERT INTO agent_issues(title,description,source,category,priority,status,created_at,updated_at) SELECT 'ISSUE-AGE-24H-REPAIR-1: issue #'||s.id||' has no live doer','Pillar autonomy. The blocker is recorded in issue_age_actions for issue '||s.id||', rung 24h. Read that row and issue_plans before choosing the remediation. The code planner, trusted intake and breach doctor own recovery; their refusal and claim checks still apply. Keep the original issue open until its own probe passes.','qnfo-fleet-control','reliability','critical','open',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM issue_age_tick_state s WHERE s.breach=1 AND s.title NOT LIKE 'ISSUE-AGE-24H-REPAIR-1:%' AND NOT EXISTS(SELECT 1 FROM agent_issues a WHERE a.status='open' AND a.title='ISSUE-AGE-24H-REPAIR-1: issue #'||s.id||' has no live doer') AND NOT EXISTS(SELECT 1 FROM agent_issues a WHERE a.title='ISSUE-AGE-24H-REPAIR-1: issue #'||s.id||' has no live doer' AND a.created_at>(CAST(strftime('%s','now') AS INTEGER)-7200)*1000) ORDER BY s.age_h DESC LIMIT 12; UPDATE remediation_contracts SET verify_transport='d1-query',status='active',verify_probe='SELECT ''0'' AS expected, CAST(COALESCE((SELECT breach FROM v_issue_age_ladder WHERE id = '||(SELECT s.id FROM issue_age_tick_state s WHERE agent_issues.title='ISSUE-AGE-24H-REPAIR-1: issue #'||s.id||' has no live doer')||'), 0) AS TEXT) AS observed',action='Verify recovery of the original issue''s live doer; its own outcome probe still controls its closure.' FROM agent_issues WHERE remediation_contracts.class='issue-'||agent_issues.id AND agent_issues.status='open' AND agent_issues.title LIKE 'ISSUE-AGE-24H-REPAIR-1:%' AND EXISTS(SELECT 1 FROM issue_age_tick_state s WHERE agent_issues.title='ISSUE-AGE-24H-REPAIR-1: issue #'||s.id||' has no live doer'); UPDATE metric_registry SET last_value=CAST((SELECT COUNT(*) FROM issue_age_tick_state WHERE breach=1) AS TEXT),last_refreshed=strftime('%Y-%m-%dT%H:%M:%SZ','now'),state='MEASURED' WHERE metric='issues_over_24h_no_doer'; END;

DROP TRIGGER IF EXISTS issue_age_live_doers_tick;

