VALUES (
  'issue-age-live-doers',
  'ISSUE-AGE-24H-1: bounded replanning and escalation outside the heavy tick trigger graph',
  'workflow',
  json_object('steps', json_array(
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'DELETE FROM issue_age_tick_state'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'INSERT INTO issue_age_tick_state SELECT l.*, COALESCE(NULLIF(k.merge_note, ''''), NULLIF(k.last_error, ''''), NULLIF(l.plan_reason, ''''), ''no live task, claim or progressing diagnosis'') FROM v_issue_age_ladder l LEFT JOIN issue_plans p ON p.issue_id = l.id LEFT JOIN code_tasks k ON k.id = p.task_id'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'INSERT INTO issue_age_replans (issue_id, outcome_was, planned_at_was, age_h) SELECT id, plan_outcome, planned_at, age_h FROM issue_age_tick_state s WHERE s.rung <> ''new'' AND s.doer IS NULL AND s.plan_outcome IN (''not-code'', ''invalid'', ''error'', ''queued'') AND COALESCE((SELECT value FROM ops_config WHERE key = ''issue_age_replan''), ''on'') <> ''off'' AND s.planned_at < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-120 minutes'') AND NOT EXISTS (SELECT 1 FROM issue_age_replans r WHERE r.issue_id = s.id AND r.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-120 minutes'')) ORDER BY CASE s.priority WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END, s.age_h DESC LIMIT 12'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE issue_plans SET outcome = ''retry'', planned_at = ''2000-01-01T00:00:00Z'', detail = substr(''ISSUE-AGE-24H-1 re-plan: '' || COALESCE(detail, ''''), 1, 600) WHERE issue_id IN (SELECT issue_id FROM issue_age_replans WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-1 minutes'')) AND outcome IN (''not-code'', ''invalid'', ''error'', ''queued'')'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'INSERT OR IGNORE INTO issue_age_actions (issue_id, rung, priority_was, priority_to, blocker) SELECT id, ''8h'', priority, CASE priority WHEN ''low'' THEN ''medium'' WHEN ''medium'' THEN ''high'' WHEN ''high'' THEN ''critical'' ELSE priority END, blocker FROM issue_age_tick_state WHERE rung IN (''8h'', ''16h'', ''24h'') AND doer IS NULL'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE agent_issues SET priority = (SELECT priority_to FROM issue_age_actions WHERE issue_id = agent_issues.id AND rung = ''8h''), updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND id IN (SELECT issue_id FROM issue_age_actions WHERE rung = ''8h'' AND ts = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'')) AND priority IN (''low'', ''medium'', ''high'')'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'INSERT OR IGNORE INTO issue_age_actions (issue_id, rung, priority_was, priority_to, blocker) SELECT id, ''16h'', priority, ''critical'', blocker FROM issue_age_tick_state WHERE rung IN (''16h'', ''24h'') AND doer IS NULL'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE agent_issues SET priority = ''critical'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND priority <> ''critical'' AND id IN (SELECT issue_id FROM issue_age_actions WHERE rung = ''16h'' AND ts = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''))'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'INSERT OR IGNORE INTO issue_age_actions (issue_id, rung, blocker) SELECT id, ''24h'', blocker FROM issue_age_tick_state WHERE breach = 1'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''ISSUE-AGE-24H-REPAIR-1: issue #'' || s.id || '' has no live doer'', ''Pillar autonomy. The blocker is recorded in issue_age_actions for issue '' || s.id || '', rung 24h. Read that row and issue_plans before choosing the remediation. The code planner, trusted intake and breach doctor own recovery; their refusal and claim checks still apply. Keep the original issue open until its own probe passes.'', ''qnfo-fleet-control'', ''reliability'', ''critical'', ''open'', CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000, CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 FROM issue_age_tick_state s WHERE s.breach = 1 AND s.title NOT LIKE ''ISSUE-AGE-24H-REPAIR-1:%'' AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title = ''ISSUE-AGE-24H-REPAIR-1: issue #'' || s.id || '' has no live doer'') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.title = ''ISSUE-AGE-24H-REPAIR-1: issue #'' || s.id || '' has no live doer'' AND a.created_at > (CAST(strftime(''%s'', ''now'') AS INTEGER) - 7200) * 1000) ORDER BY s.age_h DESC LIMIT 12'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE remediation_contracts SET verify_transport = ''d1-query'', status = ''active'', verify_probe = ''SELECT ''''0'''' AS expected, CAST(COALESCE((SELECT breach FROM v_issue_age_ladder WHERE id = '' || (SELECT s.id FROM issue_age_tick_state s WHERE agent_issues.title = ''ISSUE-AGE-24H-REPAIR-1: issue #'' || s.id || '' has no live doer'') || ''), 0) AS TEXT) AS observed'', action = ''Verify recovery of the original issue''''s live doer; its own outcome probe still controls its closure.'' FROM agent_issues WHERE remediation_contracts.class = ''issue-'' || agent_issues.id AND agent_issues.status = ''open'' AND agent_issues.title LIKE ''ISSUE-AGE-24H-REPAIR-1:%'' AND EXISTS (SELECT 1 FROM issue_age_tick_state s WHERE agent_issues.title = ''ISSUE-AGE-24H-REPAIR-1: issue #'' || s.id || '' has no live doer'')'),
    json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM issue_age_tick_state WHERE breach = 1) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''issues_over_24h_no_doer''')
  )),
  30000, 1, 2, 1, datetime('now')
